using System;
using System.Drawing;
using Script.Methods;
public partial class UserScript : ScriptMethods, IProcessMethods
{
    private Color color;
    public void Init() { color = Color.Red; }
    public bool Process() { using (Bitmap bitmap = new Bitmap(2, 2)) { bitmap.SetPixel(0, 0, color); OutputImage = new ImageData(bitmap); ConsoleWrite(bitmap.GetPixel(0, 0).Name); } return true; }
}
